//! 🧪️ Original argument and input allocations move into their canonical merged owner while displaced values close explicitly.
use super::*;
use semio_framework_job::*;
use semio_framework_value::{DslValue,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep};
use semio_framework_ui_contract::OriginalUiArgumentsMerge;
#[track_caller]
fn event(caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,g:RetainedCloneGrant,run:&mut dyn FnMut(&mut StepContext<'_>)->Result<(),OriginalTurnFailure>){let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn_with_decoder(g,decoder,|cx|run(cx)));let p=caller.receipt();assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes),"native UI merge receipt {p:?}, failure={:?}",result.as_ref().err());result.unwrap()}
fn object_witnesses(args:&Option<DslValue>,input:&Option<DslValue>)->Vec<(String,usize,Option<usize>)>{let(Some(DslValue::Object(args)),Some(DslValue::Object(input)))=(args,input)else{return Vec::new()};let mut result=Vec::new();for(key,value)in args{let value=input.iter().find(|(candidate,_)|candidate==key).map(|(_,value)|value).unwrap_or(value);result.push((key.clone(),key.as_ptr()as usize,if let DslValue::String(text)=value{Some(text.as_ptr()as usize)}else{None}));}for(key,value)in input{if !args.iter().any(|(candidate,_)|candidate==key){result.push((key.clone(),key.as_ptr()as usize,if let DslValue::String(text)=value{Some(text.as_ptr()as usize)}else{None}));}}result}
#[test]
fn original_ui_arguments_merge_preserves_original_key_and_value_custody(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:32768,maximum_capacity_bytes:16<<20,maximum_release_bytes:16<<20,maximum_depth:4096};for row in law["cases"].as_array().unwrap(){for cut in law["cancelAfter"].as_array().unwrap().iter().map(|cut|Some(cut.as_u64().unwrap()as usize)).chain([None]){
  let mut caller=caller();let mut decoder=OriginalJobDecodeOwner::empty();let mut args=(!row["args"].is_null()).then(||DslValue::from(&row["args"]));let mut input=(!row["input"].is_null()).then(||DslValue::from(&row["input"]));let witnesses=object_witnesses(&args,&input);let mut owner=None;let d=OriginalUiArgumentsMerge::birth_demands();for axis in 0..5{let mut denied=g;match axis{0=>denied.maximum_items=0,1 if d.copy_bytes>0=>denied.maximum_copy_bytes=d.copy_bytes-1,2 if d.capacity_bytes>0=>denied.maximum_capacity_bytes=d.capacity_bytes-1,3 if d.release_bytes>0=>denied.maximum_release_bytes=d.release_bytes-1,4 if d.depth>0=>denied.maximum_depth=d.depth-1,_=>continue}event(&mut caller,&mut decoder,denied,&mut|cx|{assert!(!OriginalUiArgumentsMerge::admit(&mut args,&mut input,cx,&mut owner)?);Ok(())});assert!(owner.is_none());}event(&mut caller,&mut decoder,g,&mut|cx|{assert!(OriginalUiArgumentsMerge::admit(&mut args,&mut input,cx,&mut owner)?);Ok(())});assert!(args.is_none()&&input.is_none());let active=owner.as_mut().unwrap();let mut foreign=OriginalJobDecodeOwner::empty();event(&mut caller,&mut foreign,g,&mut|cx|{assert!(active.advance(cx).is_err());Ok(())});assert!(foreign.terminal_is_empty());
  for index in 0..262144{if cut==Some(index){caller.cancel().cancel_now();break}if active.ready(){break}let d=active.demands().unwrap();for axis in 0..5{let mut denied=g;match axis{0=>denied.maximum_items=0,1 if d.copy_bytes>0=>denied.maximum_copy_bytes=d.copy_bytes-1,2 if d.capacity_bytes>0=>denied.maximum_capacity_bytes=d.capacity_bytes-1,3 if d.release_bytes>0=>denied.maximum_release_bytes=d.release_bytes-1,4 if d.depth>0=>denied.maximum_depth=d.depth-1,_=>continue}event(&mut caller,&mut decoder,denied,&mut|cx|{active.advance(cx)?;Ok(())});assert_eq!(caller.receipt(),Default::default());assert_eq!(active.demands().unwrap(),d);}event(&mut caller,&mut decoder,g,&mut|cx|{active.advance(cx)?;Ok(())});assert!(index<262143);}
  let mut output=None;if cut.is_none(){assert!(active.ready());let d=active.take_demands().unwrap();for axis in 0..5{let mut denied=g;match axis{0=>denied.maximum_items=0,1 if d.copy_bytes>0=>denied.maximum_copy_bytes=d.copy_bytes-1,2 if d.capacity_bytes>0=>denied.maximum_capacity_bytes=d.capacity_bytes-1,3 if d.release_bytes>0=>denied.maximum_release_bytes=d.release_bytes-1,4 if d.depth>0=>denied.maximum_depth=d.depth-1,_=>continue}event(&mut caller,&mut decoder,denied,&mut|cx|{assert!(!active.take_into(&mut output,cx)?);Ok(())});assert!(output.is_none()&&active.ready());}event(&mut caller,&mut decoder,g,&mut|cx|{assert!(active.take_into(&mut output,cx)?);Ok(())});assert_eq!(output.as_ref().map(|value|serde_json::to_value(value).unwrap()).unwrap_or(serde_json::Value::Null),row["expected"]);if let Some(DslValue::Object(rows))=&output{for(key,key_pointer,value_pointer)in &witnesses{let(actual_key,value)=rows.iter().find(|(candidate,_)|candidate==key).unwrap();assert_eq!(actual_key.as_ptr()as usize,*key_pointer);if let Some(pointer)=value_pointer{let DslValue::String(value)=value else{panic!("original string value changed")};assert_eq!(value.as_ptr()as usize,*pointer);}}}}
  for index in 0..262144{if active.terminal_is_empty(){break}let d=active.close_demands().unwrap();for axis in 0..5{let mut denied=g;match axis{0=>denied.maximum_items=0,1 if d.copy_bytes>0=>denied.maximum_copy_bytes=d.copy_bytes-1,2 if d.capacity_bytes>0=>denied.maximum_capacity_bytes=d.capacity_bytes-1,3 if d.release_bytes>0=>denied.maximum_release_bytes=d.release_bytes-1,4 if d.depth>0=>denied.maximum_depth=d.depth-1,_=>continue}event(&mut caller,&mut decoder,denied,&mut|cx|cx.with_original_retirement(|cx|{active.close_step(cx)?;Ok(())}));assert_eq!(caller.receipt(),Default::default());assert_eq!(active.close_demands().unwrap(),d);}event(&mut caller,&mut decoder,g,&mut|cx|cx.with_original_retirement(|cx|{active.close_step(cx)?;Ok(())}));assert!(index<262143);}event(&mut caller,&mut decoder,g,&mut|cx|cx.with_original_retirement(|cx|{let d=OriginalUiArgumentsMerge::release_demands();close_original_retained_step(cx,d,|_|{drop(owner.take());Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,released_bytes:d.release_bytes,..Default::default()}))})?;Ok(())}));let mut close=semio_framework_value::retained_clone::RetainedCloneClose::default();while output.is_some()||!close.is_empty(){event(&mut caller,&mut decoder,g,&mut|cx|cx.with_original_retirement(|cx|{let d=close.next_owner_demands::<DslValue>(output.is_some(),&None,32768)?;close_original_retained_step(cx,d,|grant|if output.is_some(){Ok(close.begin_granted(&mut output,grant)?.unwrap())}else{close.select(32768)?.step(grant)})?;Ok(())}));}retire_decoder(&mut caller,&mut decoder);caller.retire(g);
 }}
}
